INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnt eine Global Unicast-Adresse immer mit 2000::/3?', 2, '[{"text": "Ja", "correct": true, "because": "Reserviert für globale Nutzung"}, {"text": "Nein", "correct": false, "because": "Standard ist festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits umfasst der Präfix /3 bei 2000::/3?', 3, '[{"text": "3", "correct": true, "because": "Erste 3 Bits definieren den Typ"}, {"text": "32", "correct": false, "because": "Zu hoch für Präfix"}, {"text": "64", "correct": false, "because": "Typisch für Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal macht eine Adresse weltweit eindeutig?', 4, '[{"text": "Globaler Präfix", "correct": true, "because": "2000::/3 ist global zugeteilt"}, {"text": "Hohe Bitanzahl", "correct": false, "because": "Nicht spezifisch genug"}, {"text": "Kürzungsregeln", "correct": false, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2000::/3 ist für private Netze. b) Es ist weltweit routbar.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist für Unique Local"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Global Unicast-Adresse?', 5, '[{"text": "Lokale Routing-Tabellen", "correct": true, "because": "Global geroutet"}, {"text": "Präfix 2000::/3", "correct": false, "because": "Definiert Typ"}, {"text": "Interface-ID", "correct": false, "because": "Teil der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8::1 global eindeutig ist?', 2, '[{"text": "Ja", "correct": true, "because": "Fällt unter 2000::/3"}, {"text": "Nein", "correct": false, "because": "Präfix ist global"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck hat der /3-Präfix?', 3, '[{"text": "Globale Routbarkeit", "correct": true, "because": "Weltweit eindeutig"}, {"text": "Lokale Zuordnung", "correct": false, "because": "Nicht auf LAN beschränkt"}, {"text": "Multicast-Gruppen", "correct": false, "because": "Anderer Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Adresse mit 2000::/3?', 5, '[{"text": "Weltweit eindeutig", "correct": true, "because": "Global zugeteilt"}, {"text": "Internet-routbar", "correct": true, "because": "Für öffentliche Netze"}, {"text": "Nur lokal nutzbar", "correct": false, "because": "Nicht Link-Local"}, {"text": "Für Gruppen", "correct": false, "because": "Nicht Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2000::/3 ist öffentlich. b) Es ersetzt IPv4 komplett. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist technisch unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine globale Adresse?', 4, '[{"text": "Präfix 2000::/3", "correct": false, "because": "Definiert Global Unicast"}, {"text": "Routing-Information", "correct": false, "because": "Für Internet nötig"}, {"text": "Link-Local-Präfix", "correct": true, "because": "Anderer Adresstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jede 2000::/3-Adresse öffentlich?', 2, '[{"text": "Ja", "correct": true, "because": "Für globale Nutzung"}, {"text": "Nein", "correct": false, "because": "Kein privater Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei 2001:db8::1 wichtig?', 4, '[{"text": "Globaler Präfix", "correct": true, "because": "2000::/3-Teil"}, {"text": "Interface-ID", "correct": true, "because": "Identifiziert Gerät"}, {"text": "Multicast-Flag", "correct": false, "because": "Anderer Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2000::/3 nur für ISPs ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Endnutzer"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer globalen Adresse?', 3, '[{"text": "Eindeutigkeit", "correct": true, "because": "Weltweit erforderlich"}, {"text": "Kürzeste Darstellung", "correct": false, "because": "Sekundär"}, {"text": "Lokale Reichweite", "correct": false, "because": "Nicht der Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2000::/3 ist routbar. b) Es ist für lokale Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist für Link-Local"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet 2000::/3?', 5, '[{"text": "Globale Erreichbarkeit", "correct": true, "because": "Internet-routbar"}, {"text": "Eindeutige Zuordnung", "correct": true, "because": "Weltweit unik"}, {"text": "Kleine Subnetze", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer globalen Adresse unwichtig?', 3, '[{"text": "Präfix", "correct": false, "because": "Definiert Typ"}, {"text": "Routbarkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "LAN-Beschränkung", "correct": true, "because": "Global, nicht lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann 2000::/3 privat genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Für öffentliche Netze"}, {"text": "Ja", "correct": false, "because": "Unique Local ist privat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001::1 global routbar ist?', 3, '[{"text": "Ja", "correct": true, "because": "Teil von 2000::/3"}, {"text": "Nein", "correct": false, "because": "Präfix erlaubt Routing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für eine weltweite Adresse?', 4, '[{"text": "2000::/3", "correct": true, "because": "Global Unicast"}, {"text": "FE80::/10", "correct": false, "because": "Link-Local"}, {"text": "FF00::/8", "correct": false, "because": "Multicast"}]');
